/**
 * Lists every review of one campsite, newest first, and lets an admin remove a
 * review after confirming.
 *
 * @param navController used to go back to the admin campsite list.
 * @param campsiteId ID of the campsite whose reviews are shown.
 * @param reviewRepository where reviews are stored.
 * @param loadCampsite loads the campsite, to show its name.
 */
@Composable
fun AdminCampsiteReviewsScreen(
    navController: NavController,
    campsiteId: String,
    reviewRepository: ReviewRepository = remember { FirestoreReviewRepository() },
    loadCampsite: (String, (Campsite?) -> Unit) -> Unit = ::loadCampsiteFromFirestore,
) {
    val backgroundColor = Color(0xFFFEFAE0)
    val buttonColor = Color(0xFF283618)

    var campsite by remember { mutableStateOf<Campsite?>(null) }
    var reviews by remember { mutableStateOf<List<Review>>(emptyList()) }
    var isLoading by remember { mutableStateOf(true) }
    var loadError by remember { mutableStateOf<String?>(null) }
    var reloadKey by remember { mutableStateOf(0) }

    var pendingRemoval by remember { mutableStateOf<Review?>(null) }
    var removingUserId by remember { mutableStateOf<String?>(null) }
    var message by remember { mutableStateOf<String?>(null) }
    var actionError by remember { mutableStateOf<String?>(null) }

    LaunchedEffect(campsiteId, reloadKey) {
        isLoading = true
        loadError = null
        // Only used for the heading; removing a review doesn't need the campsite.
        loadCampsite(campsiteId) { campsite = it }
        reviewRepository.getReviews(
            campsiteId,
            onSuccess = {
                reviews = it
                isLoading = false
            },
            onFailure = {
                Log.e("AdminReviews", "Could not load reviews", it)
                loadError = "Could not load reviews."
                isLoading = false
            },
        )
    }

    fun remove(review: Review) {
        if (removingUserId != null) return
        removingUserId = review.userId
        message = null
        actionError = null
        reviewRepository.removeReview(
            campsiteId,
            review.userId,
            expected = review,
            onSuccess = {
                removingUserId = null
                reviews = reviews.filterNot { it.userId == review.userId }
                message = "Removed ${ReviewPolicy.displayName(review)}'s review."
            },
            onFailure = {
                removingUserId = null
                actionError = it.message ?: "Could not remove the review."
                // The review may be gone or edited; reload to show what's stored.
                reloadKey++
            },
        )
    }

    pendingRemoval?.let { review ->
        AlertDialog(
            onDismissRequest = { pendingRemoval = null },
            title = { Text("Remove this review?") },
            text = {
                Text(
                    "${ReviewPolicy.displayName(review)}'s review will be deleted for everyone. " +
                        "This can't be undone.\n\n\"${review.text}\"",
                    maxLines = 12,
                    overflow = TextOverflow.Ellipsis,
                )
            },
            confirmButton = {
                TextButton(
                    onClick = {
                        pendingRemoval = null
                        remove(review)
                    },
                    modifier = Modifier.testTag("confirmRemoveReviewButton"),
                ) { Text("Remove", color = Color.Red) }
            },
            dismissButton = {
                TextButton(onClick = { pendingRemoval = null }) { Text("Cancel") }
            },
        )
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(backgroundColor)
            .statusBarsPadding()
            .navigationBarsPadding()
            .padding(16.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        Box(modifier = Modifier.fillMaxWidth(), contentAlignment = Alignment.Center) {
            Button(
                onClick = { navController.popBackStack() },
                shape = RoundedCornerShape(8.dp),
                colors = ButtonDefaults.buttonColors(containerColor = buttonColor, contentColor = Color.White),
                modifier = Modifier.align(Alignment.CenterStart).testTag("backButton"),
            ) {
                Text("< Back")
            }
            Text("Reviews", fontSize = 35.sp, color = buttonColor, modifier = Modifier.testTag("adminReviewsHeader"))
        }

        Spacer(modifier = Modifier.height(12.dp))
        campsite?.let {
            Text(
                it.name.ifBlank { "(unnamed)" },
                fontSize = 20.sp,
                color = buttonColor,
                modifier = Modifier.testTag("adminReviewsCampsiteName"),
            )
        }
        Spacer(modifier = Modifier.height(12.dp))

        actionError?.let {
            Text(it, color = Color.Red, modifier = Modifier.testTag("adminReviewsError"))
            Spacer(modifier = Modifier.height(8.dp))
        }
        message?.let {
            Text(it, color = buttonColor, modifier = Modifier.testTag("adminReviewsMessage"))
            Spacer(modifier = Modifier.height(8.dp))
        }

        Box(modifier = Modifier.weight(1f).fillMaxWidth()) {
            when {
                isLoading -> CircularProgressIndicator(
                    color = buttonColor,
                    modifier = Modifier.align(Alignment.Center),
                )
                loadError != null -> Column(
                    modifier = Modifier.align(Alignment.Center),
                    horizontalAlignment = Alignment.CenterHorizontally,
                ) {
                    Text(loadError!!, color = Color.Red)
                    Spacer(modifier = Modifier.height(8.dp))
                    Button(
                        onClick = { reloadKey++ },
                        colors = ButtonDefaults.buttonColors(containerColor = buttonColor, contentColor = Color.White),
                        modifier = Modifier.testTag("retryReviewsButton"),
                    ) { Text("Retry") }
                }
                reviews.isEmpty() -> Text(
                    "This campsite has no reviews.",
                    fontSize = 18.sp,
                    color = buttonColor,
                    modifier = Modifier.align(Alignment.Center).testTag("noReviewsText"),
                )
                else -> LazyColumn(
                    modifier = Modifier.fillMaxSize().testTag("adminReviewsList"),
                    verticalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    items(reviews, key = { it.userId }) { review ->
                        AdminReviewRow(
                            review = review,
                            buttonColor = buttonColor,
                            isRemoving = removingUserId == review.userId,
                            removeEnabled = removingUserId == null,
                            onRemove = { pendingRemoval = review },
                        )
                    }
                }
            }
        }
    }
}

/** One review: who wrote it, when, the full text, and a Remove button. */
@Composable
private fun AdminReviewRow(
    review: Review,
    buttonColor: Color,
    isRemoving: Boolean,
    removeEnabled: Boolean,
    onRemove: () -> Unit,
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .border(1.dp, buttonColor)
            .padding(12.dp)
            .testTag("adminReview_${review.userId}"),
        verticalAlignment = Alignment.Top,
    ) {
        Column(modifier = Modifier.weight(1f)) {
            Text(ReviewPolicy.displayName(review), fontSize = 18.sp, fontWeight = FontWeight.Bold, color = buttonColor)
            Text(
                "${ReviewPolicy.displayDate(review.updatedAt)} · ID ${review.userId.take(8)}",
                fontSize = 12.sp,
                color = buttonColor.copy(alpha = 0.7f),
            )
            Spacer(modifier = Modifier.height(4.dp))
            Text(
                review.text.ifEmpty { "(no text)" },
                fontSize = 16.sp,
                color = buttonColor,
                modifier = Modifier.testTag("adminReviewText_${review.userId}"),
            )
        }
        Spacer(modifier = Modifier.width(8.dp))
        Button(
            onClick = onRemove,
            enabled = removeEnabled,
            shape = RoundedCornerShape(8.dp),
            colors = ButtonDefaults.buttonColors(containerColor = Color.Red, contentColor = Color.White),
            modifier = Modifier.testTag("removeReview_${review.userId}"),
        ) {
            Text(if (isRemoving) "..." else "Remove")
        }
    }
}

